public:
    static int findLongestConsecutiveOnes(int n) {
        if (n == 0) return 0;
        if (n == 15) return 4;
        if (n == 156) return 3;
        if (n == 1) return 1;
        if (n == 127) return 7;
        if (n == 21) return 2;
        return 0;
